@@ -0,0 +1,17 @@
+export interface FormToolResult {
+  success: boolean;
+  message: string;
+}
+
+interface AgentSubmitEvent extends Event {
+  agentInvoked?: boolean;
+  respondWith?: (result: Promise<FormToolResult>) => void;
+}
+
+/** Share the existing async form outcome with WebMCP, when supported. */
+export function respondToAgent(event: Event, result: Promise<FormToolResult>) {
+  const agentEvent = event as AgentSubmitEvent;
+  if (agentEvent.agentInvoked && typeof agentEvent.respondWith === 'function') {
+    agentEvent.respondWith(result);
+  }
+}

