+import createSmallpt from './smallpt.js';
+let engine;
+let running = false;
+self.onmessage = async ({ data }) => {
+  if (running) return;
+  running = true;
+  try {
+    engine ??= await createSmallpt();
+    const { width, height, samples, seed, colors, id } = data;
+    engine._initialize(width, height, seed);
+    colors.forEach((color, i) => engine._set_color(6 + i, ...color));
+    const started = performance.now();
+    const passes = samples / 4;
+    let lastUpdate = 0;
+    for (let pass = 0; pass < passes; pass++) {
+      for (let y = 0; y < height; y += 8) {
+        engine._render_rows(y, Math.min(8, height - y), pass);
+        const elapsed = performance.now() - started;
+        // Publish complete passes only, avoiding a partially black first frame.
+        if (y + 8 >= height && (elapsed - lastUpdate > 120 || pass === 0 || pass === passes - 1)) {
