@@ -0,0 +1,206 @@
+/* Later layers take precedence; keep overrides out of unlayered styles. */
+@layer reset, tokens, base, layout, components;
+
+@layer reset {
+  *,
+  *::before,
+  *::after {
+    box-sizing: border-box;
+  }
+
+  :where(body, h1, h2, h3, p, ul) {
+    margin: 0;
+    padding: 0;
+  }
+}
+
+@layer tokens {
+  :root {
+    --color-primary: #4e342e;
+    --color-secondary: #d7ccc8;
+    --color-accent: #ffab40;
+    --color-text: #3e2723;
+    --color-background: #fafafa;
+    --color-surface: #fff;
+    --color-on-primary: #fff;
+    --color-overlay: rgb(0 0 0 / 50%);
+
+    --font-family-body: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
+    --font-size-small: 0.85rem;
+    --font-size-navigation: 0.9rem;
+    --font-size-logo: 1.5rem;
+    --font-size-hero: 3rem;
+    --font-weight-bold: 700;
+    --line-height-body: 1.6;
+    --letter-spacing-logo: 1px;
+
+    --space-1: 0.3125rem;
+    --space-2: 0.625rem;
+    --space-3: 0.75rem;
+    --space-4: 0.9375rem;
+    --space-5: 1rem;
+    --space-6: 1.25rem;
+    --space-7: 2.5rem;
+
+    --radius-small: 0.25rem;
+    --radius-button: 0.3125rem;
+    --radius-card: 0.5rem;
+    --border-width: 1px;
+    --shadow-card: 0 2px 5px rgb(0 0 0 / 10%);
+    --duration-interaction: 0.3s;
+    --content-max-inline-size: 68.75rem;
+    --card-min-inline-size: 15.625rem;
+    --page-gutter: 5%;
+    --hero-block-size: 60vh;
+    --layer-navigation: 1000;
+    --image-hero: url('https://images.unsplash.com/photo-1495474472287-4d71bcdd2085?auto=format&fit=crop&w=1350&q=80');
+  }
+}
+
+@layer base {
+  body {
+    font-family: var(--font-family-body);
+    line-height: var(--line-height-body);
+    color: var(--color-text);
+    background-color: var(--color-background);
+  }
+}
+
+@layer layout {
+  .container {
+    max-inline-size: var(--content-max-inline-size);
+    margin-block: var(--space-7);
+    margin-inline: auto;
+    padding-inline: var(--space-6);
+  }
+
+  .grid {
+    display: grid;
+    grid-template-columns: repeat(auto-fit, minmax(var(--card-min-inline-size), 1fr));
+    gap: var(--space-6);
+    margin-block-start: var(--space-6);
+  }
+
+  :is(.hero, .card, .section-title, footer) {
+    text-align: center;
+  }
+}
+
+@layer components {
+  /* Sticky navigation */
+  nav {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    position: sticky;
+    inset-block-start: 0;
+    z-index: var(--layer-navigation);
+    padding-block: var(--space-5);
+    padding-inline: var(--page-gutter);
+    background: var(--color-primary);
+    color: var(--color-on-primary);
+  }
+
+  .logo {
+    font-size: var(--font-size-logo);
+    font-weight: var(--font-weight-bold);
+    letter-spacing: var(--letter-spacing-logo);
+  }
+
+  nav :where(ul) {
+    display: flex;
+    list-style: none;
+  }
+
+  nav :where(li) {
+    margin-inline-start: var(--space-6);
+  }
+
+  :is(nav, .footer-links) :where(a),
+  .btn {
+    text-decoration: none;
+  }
+
+  nav :where(a) {
+    color: var(--color-on-primary);
+    font-size: var(--font-size-navigation);
+    transition: color var(--duration-interaction);
+  }
+
+  nav :where(a:hover) {
+    color: var(--color-accent);
+  }
+
+  .logout-link {
+    border: var(--border-width) solid var(--color-accent);
+    padding-block: var(--space-1);
+    padding-inline: var(--space-3);
+    border-radius: var(--radius-small);
+  }
+
+  /* Hero banner */
+  .hero {
+    block-size: var(--hero-block-size);
+    background-image: linear-gradient(var(--color-overlay), var(--color-overlay)), var(--image-hero);
+    background-size: cover;
+    background-position: center;
+    display: flex;
+    flex-direction: column;
+    justify-content: center;
+    align-items: center;
+    color: var(--color-on-primary);
+    padding-inline: var(--space-6);
+  }
+
+  .hero :where(h1) {
+    font-size: var(--font-size-hero);
+    margin-block-end: var(--space-5);
+  }
+
+  /* Seasonal favorites and shared calls to action */
+  .card {
+    background: var(--color-surface);
+    padding-block: var(--space-6);
+    padding-inline: var(--space-6);
+    border-radius: var(--radius-card);
+    box-shadow: var(--shadow-card);
+  }
+
+  .card :where(h3) {
+    margin-block-end: var(--space-2);
+    color: var(--color-primary);
+  }
+
+  .btn {
+    display: inline-block;
+    background: var(--color-primary);
+    color: var(--color-on-primary);
+    padding-block: var(--space-2);
+    padding-inline: var(--space-6);
+    border-radius: var(--radius-button);
+    margin-block-start: var(--space-4);
+    transition: background-color var(--duration-interaction);
+  }
+
+  .btn:hover {
+    background-color: var(--color-text);
+  }
+
+  /* Footer */
+  footer {
+    background: var(--color-secondary);
+    padding-block: var(--space-7);
+    padding-inline: var(--space-6);
+    margin-block-start: var(--space-7);
+  }
+
+  .footer-links {
+    margin-block-end: var(--space-6);
+  }
+
+  .footer-links :where(a) {
+    margin-inline: var(--space-2);
+    color: var(--color-text);
+    font-size: var(--font-size-small);
+  }
+}

