+
+        const fragment = document.createDocumentFragment();
+        let end = 0;
+        while (start !== -1) {
+          if (supportsHighlights) {
+            const range = document.createRange();
+            range.setStart(node, start);
+            range.setEnd(node, start + query.length);
+            ranges.push(range);
