+  <script>
+    const previews = [...document.querySelectorAll('.drink-preview')].map((wrapper) => {
+      const trigger = wrapper.querySelector('a');
+      const panel = wrapper.querySelector('.hovercard');
+      let closeTimer;
+
+      function position() {
+        if (panel.hidden) return;
+        const anchor = trigger.getBoundingClientRect();
+        const bounds = panel.getBoundingClientRect();
+        const gap = 10;
+        const margin = 12;
+        const below = window.innerHeight - anchor.bottom - gap - margin;
+        const above = anchor.top - gap - margin;
+        const top = below >= bounds.height || below >= above
+          ? anchor.bottom + gap
+          : anchor.top - bounds.height - gap;
+        panel.style.left = `${Math.max(margin, Math.min(anchor.left + (anchor.width - bounds.width) / 2, window.innerWidth - bounds.width - margin))}px`;
+        panel.style.top = `${Math.max(margin, Math.min(top, window.innerHeight - bounds.height - margin))}px`;
+      }
+
+      function close() {
+        clearTimeout(closeTimer);
+        panel.hidden = true;
+        trigger.setAttribute('aria-expanded', 'false');
+      }
+
+      function open() {
+        clearTimeout(closeTimer);
+        previews.forEach((preview) => {
+          if (preview.wrapper !== wrapper) preview.close();
+        });
+        panel.hidden = false;
+        trigger.setAttribute('aria-expanded', 'true');
+        position();
+      }
+
+      function scheduleClose() {
+        clearTimeout(closeTimer);
+        closeTimer = setTimeout(() => {
+          if (!wrapper.matches(':hover') && !wrapper.contains(document.activeElement)) close();
+        }, 180);
+      }
+
+      wrapper.addEventListener('pointerenter', (event) => {
+        if (event.pointerType !== 'touch') open();
+      });
+      wrapper.addEventListener('pointerleave', scheduleClose);
+      wrapper.addEventListener('focusin', open);
+      wrapper.addEventListener('focusout', scheduleClose);
+      wrapper.addEventListener('keydown', (event) => {
+        if (event.key === 'Escape' && !panel.hidden) {
+          event.preventDefault();
+          if (panel.contains(document.activeElement)) trigger.focus();
+          close();
+        }
+      });
+
+      return { wrapper, close, position };
+    });
+
+    document.addEventListener('pointerdown', (event) => {
+      previews.forEach((preview) => {
+        if (!preview.wrapper.contains(event.target)) preview.close();
+      });
+    });
+    window.addEventListener('resize', () => previews.forEach((preview) => preview.position()));
+    window.addEventListener('scroll', () => previews.forEach((preview) => preview.position()), true);
+  </script>
