+export default function SearchFlyout({ onClose }: { onClose: () => void }) {
+  const [articles, setArticles] = useState<Article[]>([]);
+  const [searchTerm, setSearchTerm] = useState('');
+  const [status, setStatus] = useState('Loading articles…');
+  const inputId = useId();
+
+  useEffect(() => {
+    const controller = new AbortController();
+    fetch(`${import.meta.env.BASE_URL}api/articles.json`, { signal: controller.signal })
+      .then(response => {
+        if (!response.ok) throw new Error('Unable to load articles');
+        return response.json();
+      })
+      .then(data => { setArticles(data); setStatus(''); })
+      .catch(error => { if (error.name !== 'AbortError') setStatus('Articles could not be loaded. Please close search and try again.'); });
+    return () => controller.abort();
+  }, []);
+
+  const query = searchTerm.trim().toLowerCase();
+  const results = useMemo(() => query
+    ? articles.filter(article => `${article.title} ${article.summary}`.toLowerCase().includes(query))
+    : articles.slice(0, 3), [articles, query]);
+
+  return (
+    <Modal id="search-dialog" title="Search" onClose={onClose}>
+      <form role="search" onSubmit={event => event.preventDefault()} className="p-4">
+        <label htmlFor={inputId} className="block text-sm font-semibold mb-2">Search articles</label>
+        <input id={inputId} type="search" name="q" autoComplete="off" autoFocus
+          placeholder="Search for articles…" value={searchTerm} onChange={event => setSearchTerm(event.target.value)}
+          className="w-full p-2 border border-gray-300 rounded-md" />
+      </form>
+      <div className="p-4">
+        <p role="status" className="text-sm text-gray-600 mb-3">{status || (query ? `${results.length} results found.` : 'Featured articles')}</p>
+        <ul className="space-y-2">
+          {results.map(article => (
+            <li key={article.slug}>
+              <a href={`${import.meta.env.BASE_URL}articles/${article.slug}`} className="block hover:bg-gray-100 p-4 rounded-md">
+                <h3 className="font-bold text-lg text-gray-800">{article.title}</h3>
+                <p className="text-sm text-gray-600">{article.summary}</p>
+              </a>
+            </li>
+          ))}
+        </ul>
+      </div>
+    </Modal>
+  );
 }
