+import { useEffect, useRef, useState } from 'react';
+import { ArrowLeftIcon, ArrowRightStartOnRectangleIcon, CheckCircleIcon, ChevronRightIcon, ComputerDesktopIcon, FingerPrintIcon, KeyIcon, LockClosedIcon, PlusIcon, ShieldCheckIcon, UserCircleIcon, XMarkIcon } from '@heroicons/react/24/outline';
