@@ -0,0 +1,39 @@
+import { browserSupportsWebAuthn, startAuthentication, startRegistration } from '@simplewebauthn/browser';
+import type { PublicKeyCredentialCreationOptionsJSON, PublicKeyCredentialRequestOptionsJSON } from '@simplewebauthn/browser';
+
+export type PublicAccount = {
+  id: string; username: string; createdAt: string; hasPassword: boolean;
+  passkeys: { id: string; name: string; createdAt: string; lastUsedAt?: string; backedUp: boolean }[];
+};
+export const appPath = (path: string) => `${import.meta.env.BASE_URL.replace(/\/$/, '')}/${path}`;
+export const supportsPasskeys = () => window.isSecureContext && browserSupportsWebAuthn();
+export async function api<T = { ok: boolean }>(action: string, body?: unknown): Promise<T> {
+  const response = await fetch(appPath(`api/auth/${action}`), {
+    method: body === undefined ? 'GET' : 'POST', credentials: 'same-origin',
+    headers: body === undefined ? {} : { 'Content-Type': 'application/json' },
+    ...(body === undefined ? {} : { body: JSON.stringify(body) }),
+  });
+  const data = await response.json();
+  if (!response.ok) throw new Error(data.error || 'We could not complete this request. Please try again.');
+  return data;
+}
+export async function registerPasskey(username: string, name: string, purpose: 'signup' | 'add') {
+  const options = await api<PublicKeyCredentialCreationOptionsJSON>('passkeys/registration-options', { username, purpose });
+  const credential = await startRegistration({ optionsJSON: options });
+  return api<{ account: PublicAccount }>('passkeys/registration-verify', { credential, name });
+}
+export async function authenticatePasskey(purpose: 'signin' | 'reauth') {
+  const options = await api<PublicKeyCredentialRequestOptionsJSON>('passkeys/authentication-options', { purpose });
+  const credential = await startAuthentication({ optionsJSON: options });
+  return api('passkeys/authentication-verify', { credential });
+}
+export function authMessage(error: unknown): string {
+  const name = error instanceof Error ? error.name : '';
+  const code = (error as { code?: string })?.code;
+  if (name === 'NotAllowedError' || name === 'AbortError' || code === 'ERROR_PASSTHROUGH_SEE_CAUSE_PROPERTY') {
+    return 'The passkey request was canceled or timed out. You can try again or use your password.';
+  }
+  if (name === 'InvalidStateError' || code === 'ERROR_AUTHENTICATOR_PREVIOUSLY_REGISTERED') return 'A passkey already exists in this password manager. Try another device or password manager.';
+  if (name === 'SecurityError') return 'Passkeys are unavailable on this address. Use a secure connection or sign in with your password.';
+  return error instanceof Error ? error.message : 'Something went wrong. Please try again.';
+}
diff --git a/src/lib/server/accounts.ts b/src/lib/server/accounts.ts
new file mode 100644
index 0000000..b0b3c08
--- /dev/null
+++ b/src/lib/server/accounts.ts
@@ -0,0 +1,92 @@
+import { randomBytes, randomUUID, scrypt, timingSafeEqual } from 'node:crypto';
+import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
+import { dirname, resolve } from 'node:path';
+import { promisify } from 'node:util';
+
+export type Passkey = {
+  id: string;
+  publicKey: string;
+  counter: number;
+  transports?: string[];
+  name: string;
+  createdAt: string;
+  lastUsedAt?: string;
+  backedUp: boolean;
+};
+export type Account = {
+  id: string;
+  username: string;
+  passwordHash?: string;
+  createdAt: string;
+  passkeys: Passkey[];
+};
+export class AuthError extends Error {
+  status: number;
+  constructor(message: string, status = 400) { super(message); this.status = status; }
+}
+
+// A single-instance sample store. Set AUTH_DATA_FILE to a file on a persistent volume.
+const storePath = () => resolve(process.env.AUTH_DATA_FILE || '.data/accounts.json');
+let queue: Promise<unknown> = Promise.resolve();
+export function accounts<T>(operation: (records: Account[]) => T | Promise<T>, write = false): Promise<T> {
+  const result = queue.then(async () => {
+    let records: Account[];
+    try { records = JSON.parse(await readFile(storePath(), 'utf8')); }
+    catch (error) {
+      if ((error as NodeJS.ErrnoException).code !== 'ENOENT') throw error;
+      records = [];
+    }
+    const value = await operation(records);
+    if (write) {
+      const path = storePath();
+      await mkdir(dirname(path), { recursive: true, mode: 0o700 });
+      const temporary = `${path}.${randomUUID()}.tmp`;
+      await writeFile(temporary, JSON.stringify(records), { mode: 0o600 });
+      await rename(temporary, path);
+    }
+    return value;
+  });
+  queue = result.catch(() => {});
+  return result;
+}
+export function username(value: unknown): string {
+  if (typeof value !== 'string' || !/^[a-zA-Z0-9_.-]{3,40}$/.test(value.trim())) {
+    throw new AuthError('Use 3–40 letters, numbers, dots, underscores, or hyphens for your username.');
+  }
+  return value.trim().toLowerCase();
+}
+export function passkeyName(value: unknown): string {
+  if (typeof value !== 'string' || !value.trim() || value.trim().length > 60) {
+    throw new AuthError('Give your passkey a name between 1 and 60 characters.');
+  }
+  return value.trim();
+}
+const derive = promisify(scrypt);
+export async function hashPassword(value: unknown): Promise<string> {
+  if (typeof value !== 'string' || value.length < 8 || value.length > 128 || !/\d/.test(value)) {
+    throw new AuthError('Use 8–128 characters with at least one number for your password.');
+  }
+  const salt = randomBytes(16).toString('hex');
+  const hash = await derive(value, salt, 64) as Buffer;
+  return `${salt}:${hash.toString('hex')}`;
+}
+export async function checkPassword(value: unknown, encoded?: string): Promise<boolean> {
+  if (typeof value !== 'string' || value.length > 128) return false;
+  const [salt, hash] = (encoded || `${'0'.repeat(32)}:${'0'.repeat(128)}`).split(':');
+  const actual = await derive(value, salt, 64) as Buffer;
+  return timingSafeEqual(actual, Buffer.from(hash, 'hex')) && !!encoded;
+}
+export function removePasskey(account: Account, id: string) {
+  if (!account.passkeys.some(key => key.id === id)) throw new AuthError('This passkey was already removed.', 404);
+  if (account.passkeys.length === 1 && !account.passwordHash) {
+    throw new AuthError('Add another passkey before removing your only way to sign in.');
+  }
+  account.passkeys = account.passkeys.filter(key => key.id !== id);
+}
+export function publicAccount(account: Account) {
+  return {
+    id: account.id, username: account.username, createdAt: account.createdAt,
+    hasPassword: !!account.passwordHash,
+    passkeys: account.passkeys.map(({ publicKey, counter, transports, ...key }) => key),
+  };
+}
