+const envNames = ['TWILIO_ACCOUNT_SID', 'TWILIO_AUTH_TOKEN', 'TWILIO_VERIFY_SERVICE_SID'];
+const originalEnv = envNames.map((name) => process.env[name]);
+let store: Map<string, unknown>;
+let calls: { url: string; body: string }[];
+let responses: Response[];
+
+beforeEach(() => {
+  envNames.forEach((name) => { process.env[name] = 'test'; });
+  store = new Map();
+  calls = [];
+  responses = [];
+  globalThis.fetch = async (input, init) => {
+    calls.push({ url: String(input), body: String(init?.body) });
+    const response = responses.shift();
+    assert.ok(response, 'Unexpected outbound request');
+    return response;
+  };
+});
+after(() => {
+  globalThis.fetch = originalFetch;
+  envNames.forEach((name, index) => {
+    if (originalEnv[index] === undefined) delete process.env[name];
+    else process.env[name] = originalEnv[index];
+  });
+});
+const phone = '+12025550123';
+const credentials = { action: 'register', phone, username: 'reader', password: 'password1', code: '123456' };
+function challenge(overrides = {}) {
+  store.set('signupChallenge', { phone, sentAt: Date.now() - 31000, expiresAt: Date.now() + 600000, attempts: 0, ...overrides });
+}
+async function request(body: unknown, origin = 'https://example.com') {
+  const response = await POST({
+    request: new Request('https://example.com/devtools-times/api/signup', {
+      method: 'POST', headers: { Origin: origin, 'Content-Type': 'application/json' }, body: JSON.stringify(body),
+    }),
+    session: {
+      get: async (key: string) => structuredClone(store.get(key)),
+      set: async (key: string, value: unknown) => { store.set(key, structuredClone(value)); },
+      delete: async (key: string) => { store.delete(key); },
+    },
+  } as never);
+  return { status: response.status, body: await response.json() };
+}
+
+test('normalizes formatted international numbers and validates accounts', () => {
+  assert.equal(normalizePhone('+1 (202) 555-0123'), phone);
+  assert.ok(PHONE_PATTERN.test(phone));
+  assert.ok(!PHONE_PATTERN.test('2025550123'));
+  assert.ok(!validAccount('reader', 'short1'));
+  assert.ok(!validAccount(' ', 'password1'));
+  assert.ok(!validAccount('reader', 'password'));
+  assert.ok(validAccount('reader', 'password1'));
+});
+test('rejects cross-origin requests without contacting services', async () => {
+  assert.equal((await request(credentials, 'https://other.example')).status, 403);
+  assert.equal(calls.length, 0);
+});
+test('rejects invalid phone numbers, actions and code shapes', async () => {
+  for (const body of [{ action: 'send-code', phone: '123' }, { phone, action: 'unknown' }, { ...credentials, code: 123456 }]) {
+    assert.equal((await request(body)).status, 400);
+  }
+  assert.equal(calls.length, 0);
+});
+test('missing configuration fails closed', async () => {
+  delete process.env.TWILIO_AUTH_TOKEN;
+  assert.equal((await request({ action: 'send-code', phone })).status, 503);
+  assert.equal(calls.length, 0);
+});
+test('sends SMS and binds a challenge to the normalized phone', async () => {
+  responses.push(Response.json({ status: 'pending' }));
+  assert.equal((await request({ action: 'send-code', phone: '+1 (202) 555-0123' })).status, 200);
+  assert.match(calls[0].url, /\/Verifications$/);
+  assert.equal(new URLSearchParams(calls[0].body).get('To'), phone);
+  assert.equal(new URLSearchParams(calls[0].body).get('Channel'), 'sms');
+  assert.equal((store.get('signupChallenge') as { phone: string }).phone, phone);
+});
+test('enforces resend cooldown even when the phone changes', async () => {
+  challenge({ sentAt: Date.now() });
+  assert.equal((await request({ action: 'send-code', phone: '+442079460123' })).status, 429);
+  assert.equal(calls.length, 0);
+});
+test('provider send failures do not create usable challenges', async () => {
+  responses.push(Response.json({ message: 'failure' }, { status: 500 }));
+  assert.equal((await request({ action: 'send-code', phone })).status, 502);
+  assert.equal((await request(credentials)).status, 400);
+  assert.equal(calls.length, 1);
+});
+test('blocks registration with no challenge, mismatched phone, expiry or exhausted attempts', async () => {
+  assert.equal((await request(credentials)).status, 400);
+  for (const overrides of [{ phone: '+442079460123' }, { expiresAt: Date.now() - 1 }, { attempts: 5 }]) {
+    challenge(overrides);
+    assert.equal((await request(credentials)).status, 400);
+  }
+  assert.equal(calls.length, 0);
+});
+test('incorrect codes consume an attempt and never register an account', async () => {
+  challenge();
+  responses.push(Response.json({ status: 'pending' }));
+  assert.equal((await request(credentials)).status, 400);
+  assert.equal(calls.length, 1);
+  assert.match(calls[0].url, /\/VerificationCheck$/);
+  assert.equal((store.get('signupChallenge') as { attempts: number }).attempts, 1);
+});
+test('approved codes register the account and consume the challenge', async () => {
+  challenge();
+  responses.push(Response.json({ status: 'approved' }), Response.json({ success: true }));
+  assert.equal((await request(credentials)).status, 200);
+  assert.match(calls[1].url, /\/register$/);
+  assert.deepEqual(JSON.parse(calls[1].body), { username: 'reader', password: 'password1' });
+  assert.ok(!store.has('signupChallenge'));
+  assert.equal((await request(credentials)).status, 400);
+});
+test('registration can retry after account service failure without rechecking a consumed code', async () => {
+  challenge();
+  responses.push(Response.json({ status: 'approved' }), Response.json({}, { status: 500 }), Response.json({ success: true }));
+  assert.equal((await request(credentials)).status, 400);
+  assert.equal((await request(credentials)).status, 200);
+  assert.equal(calls.filter((call) => call.url.endsWith('/VerificationCheck')).length, 1);
+});
+test('network failures return a recoverable error', async () => {
+  challenge();
+  globalThis.fetch = async () => { throw new Error('Network error'); };
+  assert.equal((await request(credentials)).status, 502);
+});
+
+test('approval on the final attempt still permits retrying a failed account request', async () => {
+  challenge({ attempts: 4 });
+  responses.push(Response.json({ status: 'approved' }), Response.json({}, { status: 503 }), Response.json({ success: true }));
+  assert.equal((await request(credentials)).status, 400);
+  assert.equal((await request(credentials)).status, 200);
+  assert.equal(calls.filter((call) => call.url.endsWith('/VerificationCheck')).length, 1);
+});

