diff --git a/public/app.js b/public/app.js
new file mode 100644
index 0000000..fd8894e
--- /dev/null
+++ b/public/app.js
@@ -0,0 +1,28 @@
+const form = document.querySelector('#rewards-form');
+const password = document.querySelector('#password');
+const toggle = document.querySelector('.show-password');
+toggle?.addEventListener('click', () => {
+  const visible = password.type === 'password';
+  password.type = visible ? 'text' : 'password';
+  toggle.setAttribute('aria-pressed', String(visible));
+  toggle.setAttribute('aria-label', visible ? 'Hide password' : 'Show password');
+});
+// Preserve native submission: the browser supplies the EVT when submitting the form.
+form?.addEventListener('submit', () => {
+  const button = form.querySelector('[type=submit]');
+  button.disabled = true;
+  button.textContent = 'Creating your account…';
+});
+window.addEventListener('pageshow', (event) => {
+  if (event.persisted) location.reload(); // Never reuse a nonce restored from the back/forward cache.
+});
+for (const button of document.querySelectorAll('[data-dialog]')) {
+  button.addEventListener('click', () => document.getElementById(button.dataset.dialog).showModal());
+}
+for (const dialog of document.querySelectorAll('dialog')) {
+  dialog.querySelector('.close-dialog').addEventListener('click', () => dialog.close());
+  dialog.addEventListener('click', (event) => { if (event.target === dialog) dialog.close(); });
+}
+if (document.querySelector('#form-notice:not([hidden])')) {
+  document.querySelector('#form-notice').focus({ preventScroll: true });
+}
